   216|async function readDoc<T>(name: string, fallback: T): Promise<T> {
   217|  const cached = docCache.get(name);
   218|  if (cached && Date.now() - cached.at < CACHE_TTL_MS) return cached.value as T;
   219|
   220|  // 1. Try Supabase durable store FIRST — it is always up-to-date because
   221|  //    writeDoc always mirrors to it. S3 may have stale data when S3 writes
   222|  //    are failing (expired credentials), so Supabase must take priority.
   223|  const durable = await readDurableFallback<T>(name);
   224|  if (durable !== null) {
   225|    docCache.set(name, { at: Date.now(), value: durable });
   226|    return durable;
   227|  }
   228|
   229|  // 2. Try S3 (secondary — may have data not yet mirrored to Supabase).
   230|  try {
   231|    const { GetObjectCommand } = await import('@aws-sdk/client-s3');
   232|    const s3 = await getS3();
   233|    const res = await s3.send(new GetObjectCommand({ Bucket: bucket(), Key: `${PLATFORM_PREFIX}/${name}` }));
   234|    const bytes = await res.Body?.transformToByteArray();
   235|    if (bytes) {
   236|      const value = JSON.parse(Buffer.from(bytes).toString('utf-8')) as T;
   237|      docCache.set(name, { at: Date.now(), value });
   238|      // Mirror to Supabase so future reads prefer the durable copy.
   239|      await writeDurableFallback(name, value);
   240|      return value;
   241|    }
   242|  } catch {
   243|    // S3 read failed — fall through to cache/fallback.
   244|  }
   245|
   246|  // 3. Return cached (possibly stale) or the provided fallback.
   247|  return (cached?.value as T | undefined) ?? fallback;
   248|}
   249|
   250|async function writeDoc<T>(name: string, value: T): Promise<void> {
   251|  // Always update the in-memory cache first — this ensures the current
   252|  // instance reads the updated value immediately.
   253|  docCache.set(name, { at: Date.now(), value });
   254|
   255|  // 1. ALWAYS write to Supabase durable store first — this is the permanent
   256|  //    persistence layer that survives restarts, deploys, and S3 credential
   257|  //    expiry. It is also the primary read source, so it must always be current.
   258|  const durableOk = await writeDurableFallback(name, value);
   259|  if (durableOk) {
   260|    // Supabase write succeeded — this is the source of truth.
   261|  } else {
   262|    console.warn(`[video-platform-store] Supabase durable write failed for ${name} — falling back to S3.`);
   263|  }
   264|
   265|  // 2. Also try S3 (secondary) — best-effort mirror. If S3 is unavailable
   266|  //    (expired credentials), the Supabase copy is already authoritative.
   267|  try {
   268|    const { PutObjectCommand } = await import('@aws-sdk/client-s3');
   269|    const s3 = await getS3();
   270|    await s3.send(new PutObjectCommand({
   271|      Bucket: bucket(),
   272|      Key: `${PLATFORM_PREFIX}/${name}`,
   273|      Body: Buffer.from(JSON.stringify(value), 'utf-8'),
   274|      ContentType: 'application/json',
   275|      CacheControl: 'no-cache',
   276|    }));
   277|  } catch (err) {
   278|    // S3 write failed (e.g. expired AWS credentials, Access Denied).
   279|    // The Supabase durable copy is already written, so data WILL persist.
   280|    console.warn(`[video-platform-store] S3 writeDoc failed for ${name}: ${err instanceof Error ? err.message : 'unknown error'} — Supabase durable copy is authoritative.`);
   281|  }
