   802|  const ageHours = Math.max(0, (Date.now() - Date.parse(video.created_at)) / 3_600_000);
   803|  score += 40 * Math.exp(-ageHours / 168);
   804|
   805|  const engagement = video.like_count * 3 + video.comment_count * 4 + video.share_count * 5 + video.save_count * 4;
   806|  score += Math.log1p(engagement) * 10;
   807|
   808|  if (stats) {
   809|    score += Math.log1p(stats.views) * 4;
   810|    score += Math.log1p(stats.completions) * 6;
   811|    score += Math.log1p(stats.watch_ms / 1000) * 2;
   812|  }
   813|
   814|  if (meta) {
