   816|    if (ctx.profile?.audience && meta.audiences.includes(ctx.profile.audience)) score += 18;
   817|    if (ctx.zip && meta.zip) {
   818|      if (meta.zip === ctx.zip) score += 25;
   819|      else if (meta.zip.slice(0, 3) === ctx.zip.slice(0, 3)) score += 12;
