   273|      Body: Buffer.from(JSON.stringify(value), 'utf-8'),
   274|      ContentType: 'application/json',
   275|      CacheControl: 'no-cache',
   276|    }));
   277|  } catch (err) {
   278|    // S3 write failed (e.g. expired AWS credentials, Access Denied).
   279|    // The Supabase durable copy is already written, so data WILL persist.
   280|    console.warn(`[video-platform-store] S3 writeDoc failed for ${name}: ${err instanceof Error ? err.message : 'unknown error'} — Supabase durable copy is authoritative.`);
