   341|export type PlatformEvent = {
   342|  type: 'view' | 'watch' | 'complete' | 'double_tap_like' | 'share' | 'profile';
   343|  video_id?: string;
   344|  viewer_id?: string;
   345|  watch_ms?: number;
   346|  zip?: string;
   347|  audience?: string;
   348|  preferences?: string[];
   349|};
   350|
   351|function emptyStats(): VideoStats {
