   353|}
   354|
   355|export async function recordEvents(events: PlatformEvent[]): Promise<{ recorded: number }> {
   356|  const doc = await readDoc<AnalyticsDoc>('analytics.json', { videos: {}, history: {} });
   357|  let recorded = 0;
   358|  let profileTouched = false;
   359|  const profileDoc = await readDoc<ProfilesDoc>('profiles.json', {});
   360|
   361|  for (const ev of events.slice(0, 100)) {
   362|    if (ev.type === 'profile' && ev.viewer_id) {
   363|      const existing = profileDoc[ev.viewer_id] ?? { zip: null, audience: null, preferences: [], updated_at: nowIso() };
   364|      profileDoc[ev.viewer_id] = {
   365|        zip: typeof ev.zip === 'string' && ev.zip ? ev.zip : existing.zip,
   366|        audience: typeof ev.audience === 'string' && ev.audience ? ev.audience : existing.audience,
   367|        preferences: Array.isArray(ev.preferences) ? ev.preferences.slice(0, 20) : existing.preferences,
   368|        updated_at: nowIso(),
   369|      };
   370|      profileTouched = true;
   371|      recorded += 1;
   372|      continue;
   373|    }
   374|    const videoId = typeof ev.video_id === 'string' ? ev.video_id.trim() : '';
   375|    if (!videoId) continue;
   376|    const stats = doc.videos[videoId] ?? emptyStats();
   377|    const viewerId = typeof ev.viewer_id === 'string' ? ev.viewer_id.trim() : '';
   378|
   379|    switch (ev.type) {
   380|      case 'view':
   381|        stats.views += 1;
   382|        if (viewerId && !stats.viewer_ids.includes(viewerId)) {
   383|          stats.viewer_ids.push(viewerId);
   384|          if (stats.viewer_ids.length > MAX_VIEWER_IDS_PER_VIDEO) stats.viewer_ids.shift();
   385|          stats.unique_viewers += 1;
   386|        }
   387|        if (viewerId) {
   388|          const hist = doc.history[viewerId] ?? { watched: [], updated_at: nowIso() };
   389|          hist.watched = hist.watched.filter((id) => id !== videoId);
   390|          hist.watched.push(videoId);
   391|          if (hist.watched.length > MAX_HISTORY_PER_VIEWER) hist.watched.shift();
   392|          hist.updated_at = nowIso();
   393|          doc.history[viewerId] = hist;
   394|        }
   395|        break;
   396|      case 'watch':
   397|        stats.watch_ms += Math.max(0, Math.min(Number(ev.watch_ms) || 0, 3_600_000));
   398|        break;
   399|      case 'complete':
   400|        stats.completions += 1;
   401|        break;
   402|      case 'double_tap_like':
   403|        stats.double_tap_likes += 1;
   404|        break;
   405|      case 'share':
   406|        stats.shares += 1;
   407|        break;
   408|      default:
   409|        continue;
   410|    }
   411|    stats.last_event_at = nowIso();
   412|    doc.videos[videoId] = stats;
   413|    recorded += 1;
   414|  }
   415|
   416|  await writeDoc('analytics.json', doc);
   417|  if (profileTouched) await writeDoc('profiles.json', profileDoc);
   418|  return { recorded };
   419|}
