   597|function buildLivePlaylist(session: LiveSession, ended: boolean): string {
   598|  const targetDuration = Math.max(4, Math.ceil(session.segments.reduce((max, s) => Math.max(max, s.duration), 4)));
   599|  const lines: string[] = [
   600|    '#EXTM3U',
   601|    '#EXT-X-VERSION:3',
   602|    `#EXT-X-TARGETDURATION:${targetDuration}`,
   603|    '#EXT-X-MEDIA-SEQUENCE:0',
   604|    '#EXT-X-PLAYLIST-TYPE:EVENT',
   605|  ];
   606|  for (const seg of session.segments) {
   607|    lines.push(`#EXTINF:${seg.duration.toFixed(3)},`);
   608|    lines.push(`seg_${String(seg.seq).padStart(5, '0')}.ts`);
   609|  }
   610|  if (ended) lines.push('#EXT-X-ENDLIST');
   611|  return `${lines.join('\n')}\n`;
   612|}
