   665|/**
   666| * Ingest one MPEG-TS segment over HTTP: store it in S3, extend the EVENT HLS
   667| * playlist, and flip the session to 'live' on the first segment.
   668| */
   669|export async function ingestLiveSegment(sessionId: string, bytes: Uint8Array, durationSeconds: number): Promise<LiveSession> {
   670|  const doc = await readDoc<LiveDoc>('live.json', {});
   671|  const raw = doc[sessionId];
   672|  if (!raw) throw new Error('live session not found');
   673|  const session = normalizeLiveSession(raw);
   674|  if (session.status === 'ended' || session.status === 'failed') {
   675|    throw new Error(`live session is ${session.status}; ingest rejected`);
   676|  }
   677|  if (session.ingest_url === null) throw new Error('session uses an external playback_url; ingest not enabled');
   678|  if (session.segments.length >= MAX_LIVE_SEGMENTS) throw new Error('live session segment limit reached');
   679|
   680|  const seq = session.segment_count;
   681|  const duration = Number.isFinite(durationSeconds) && durationSeconds > 0 ? Math.min(durationSeconds, 30) : 4;
   682|  const segmentKey = `${LIVE_STORAGE_PREFIX}/${sessionId}/seg_${String(seq).padStart(5, '0')}.ts`;
   683|  try {
   684|    await putLiveObject(segmentKey, bytes, 'video/mp2t', 'public, max-age=31536000, immutable');
   685|    session.segments.push({ seq, duration, size: bytes.byteLength, uploaded_at: nowIso() });
   686|    session.segment_count = seq + 1;
   687|    session.last_segment_at = nowIso();
   688|    if (session.status === 'created') {
   689|      session.status = 'live';
   690|      session.started_at = nowIso();
   691|    }
   692|    await putLiveObject(`${LIVE_STORAGE_PREFIX}/${sessionId}/live.m3u8`, buildLivePlaylist(session, false), 'application/vnd.apple.mpegurl', 'no-cache');
   693|  } catch (err) {
   694|    session.status = 'failed';
   695|    session.ended_at = nowIso();
   696|    session.ended_reason = `ingest failed: ${err instanceof Error ? err.message : 'storage error'}`;
   697|    doc[sessionId] = session;
   698|    await writeDoc('live.json', doc);
   699|    await syncLiveSessionRow(session);
   700|    throw err;
   701|  }
   702|  doc[sessionId] = session;
   703|  await writeDoc('live.json', doc);
   704|  await syncLiveSessionRow(session);
   705|  return session;
   706|}
